const output = $input.first().json.output;

let briefing;
try {
  briefing = JSON.parse(output);
} catch(e) {
  const match = output.match(/```json([\s\S]*?)```/);
  if (match) {
    try { briefing = JSON.parse(match[1].trim()); }
    catch(e2) { briefing = { raw: output }; }
  } else {
    briefing = { raw: output };
  }
}

const briefingStr = JSON.stringify(briefing, null, 2);

return [{
  json: {
    briefing_analisado: briefing,
    briefing_str: briefingStr,
