const output = $input.first().json.output;
const briefing = $('Formatar Para Validador IG').first().json.briefing_str;
const copy = $('Formatar Para Validador IG').first().json.copy_str;
const arte = $('Formatar Para Validador IG').first().json.arte_str;

let val;
try {
  val = JSON.parse(output);
} catch(e) {
  const match = output.match(/```json([\s\S]*?)```/);
  if (match) {
    try { val = JSON.parse(match[1].trim()); }
    catch(e2) { val = { aprovado: false, veredito: 'ERRO_PARSE', raw: output }; }
  } else {
    val = { aprovado: false, veredito: 'ERRO_PARSE', raw: output };
  }
}

return [{
  json: {
    canal: 'instagram',
    data: new Date().toLocaleString('pt-BR'),
    validacao: val,
    aprovado: val.aprovado === true,
    score_total: val.scores?.total || 0,
    veredito: val.veredito || 'ERRO',
    pontos_fortes: (val.pontos_fortes || []).join(' | '),
    pontos_fracos: (val.pontos_fracos || []).join(' | '),
    ajustes: val.ajustes_recomendados || '',
    briefing: briefing,
    copy: copy,
    arte: arte
  }
}];

